const {spawnSync} = require("child_process");
const fs = require("fs");
const DIR = "/workspace/dev/cases/cli-and-errors/";
const files = fs.readdirSync(DIR).filter(f=>f.endsWith(".txt")).sort();
const out = [];
for (const f of files) {
  const v = fs.readFileSync(DIR+f, "utf8");
  const r = spawnSync("/workspace/dataset/test9_executable", ["--a", v], {encoding:"utf8"});
  const norm = s => s.replace(/\[PYI-\d+:ERROR\]/g, "[PYI-<pid>:ERROR]");
  out.push({f, val: v, rc: r.status, stdout: r.stdout, stderr: norm(r.stderr)});
}
fs.writeFileSync("/workspace/tmp/results.json", JSON.stringify(out, null, 1));
// terse report
for (const o of out) {
  console.log("### " + o.f);
  console.log("VAL=" + JSON.stringify(o.val));
  console.log("RC=" + o.rc);
  if (o.stdout) console.log("OUT=" + JSON.stringify(o.stdout));
  if (o.stderr) console.log("ERR=" + JSON.stringify(o.stderr));
  console.log("");
}

